#!/usr/bin/env bash
set -euo pipefail

EXPECTED_REPO="16usa/memeflow-"
EXPECTED_BRANCH="main"
COMMIT_MESSAGE="Add Solana wallet copy trading"

fail(){ echo "ERROR: $*" >&2; exit 1; }

REPO_ROOT="$(git rev-parse --show-toplevel 2>/dev/null || true)"
[[ -n "$REPO_ROOT" ]] || fail "Git repository not found. Run this from the MEMEFLOW Replit Shell."
cd "$REPO_ROOT"

APP="$REPO_ROOT/memeflow-app"
[[ -f "$APP/app-server.mjs" ]] || fail "memeflow-app/app-server.mjs not found under $REPO_ROOT"
[[ -f "$APP/src/settings.mjs" ]] || fail "memeflow-app/src/settings.mjs not found under $REPO_ROOT"

BRANCH="$(git branch --show-current)"
[[ "$BRANCH" == "$EXPECTED_BRANCH" ]] || fail "Expected branch '$EXPECTED_BRANCH', current branch is '$BRANCH'."

ORIGIN_URL="$(git remote get-url origin 2>/dev/null || true)"
[[ -n "$ORIGIN_URL" ]] || fail "Git remote 'origin' is missing."
case "$ORIGIN_URL" in
  *"$EXPECTED_REPO"*|*"16usa/memeflow-.git"*) ;;
  *) fail "Wrong repository: origin=$ORIGIN_URL (expected $EXPECTED_REPO)" ;;
esac

if [[ -n "$(git status --porcelain)" ]]; then
  echo "Working tree has local changes. Patch stopped so it does not mix or overwrite them:" >&2
  git status --short >&2
  exit 2
fi

echo "==> Syncing $EXPECTED_BRANCH"
git fetch origin "$EXPECTED_BRANCH"
git pull --ff-only origin "$EXPECTED_BRANCH"

BASE_SHA="$(git rev-parse HEAD)"
STAMP="$(date -u +%Y%m%dT%H%M%SZ)"
BACKUP_BRANCH="backup/copy-trading-v1-$STAMP"

echo "==> Creating remote backup branch: $BACKUP_BRANCH"
git branch "$BACKUP_BRANCH" "$BASE_SHA"
git push origin "$BACKUP_BRANCH:$BACKUP_BRANCH"

PATCHER="$APP/apply-copy-trading-v1.mjs"
cat > "$PATCHER.b64" <<'PAYLOAD_EOF'

PAYLOAD_EOF
base64 -d "$PATCHER.b64" > "$PATCHER"
rm -f "$PATCHER.b64"

node --check "$PATCHER"

echo "==> Checking patch anchors"
(
  cd "$APP"
  node apply-copy-trading-v1.mjs --check
)

echo "==> Applying COPY TRADING V1"
(
  cd "$APP"
  node apply-copy-trading-v1.mjs
)

echo "==> Running full MEMEFLOW test suite"
(
  cd "$APP"
  npm test
)

cd "$REPO_ROOT"
git add \
  memeflow-app/app-server.mjs \
  memeflow-app/index.html \
  memeflow-app/package.json \
  memeflow-app/src/settings.mjs \
  memeflow-app/src/copy-trader.mjs \
  memeflow-app/copy-trading-ui.js \
  memeflow-app/tests/copy-trading.mjs \
  memeflow-app/apply-copy-trading-v1.mjs

if git diff --cached --quiet; then
  echo "No tracked changes to commit. COPY TRADING V1 may already be installed."
  exit 0
fi

echo "==> Committing"
git commit -m "$COMMIT_MESSAGE"
NEW_SHA="$(git rev-parse HEAD)"

echo "==> Pushing $EXPECTED_BRANCH"
git push origin "$EXPECTED_BRANCH"

echo
echo "DONE"
echo "Base commit:    $BASE_SHA"
echo "Pushed commit:  $NEW_SHA"
echo "Backup branch:  $BACKUP_BRANCH"
echo
echo "Rollback (safe):"
echo "  git revert $NEW_SHA && git push origin $EXPECTED_BRANCH"
